using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Text;
using System.Web.Script.Serialization;
using System.Windows.Media;
using System.Windows.Threading;
public class VoiceRuntime:IDisposable {
 readonly string folder,settingsPath;readonly JavaScriptSerializer json=new JavaScriptSerializer();readonly MediaPlayer player=new MediaPlayer();readonly Stopwatch clock=Stopwatch.StartNew();readonly VoicePolicy policy=new VoicePolicy();readonly Random random=new Random();readonly DispatcherTimer watchdog=new DispatcherTimer();
 public readonly VoiceCatalog Candidates=new VoiceCatalog();public readonly VoiceCatalog Catalog;public VoiceSettings Settings;public string Status="原声就绪",LoadError;public bool Playing{get;private set;}public bool TravelVoice{get;private set;}public bool AmbientVoice{get;private set;}public string CurrentId{get;private set;}public string CurrentKind{get;private set;}public string CurrentKey{get;private set;}public event Action Changed,Completed;public event Action<VoiceClip> Started;public int OpenedCount,EndedCount;int lastIndex=-1;VoiceClip currentClip;
 public VoiceRuntime(string home,string dataFolder=null){folder=Path.Combine(home,"voices");settingsPath=Path.Combine(dataFolder??home,"voice-settings.json");Catalog=new VoiceCatalog();Settings=new VoiceSettings();try{string path=Path.Combine(folder,"catalog.json");if(File.Exists(path))Catalog=json.Deserialize<VoiceCatalog>(File.ReadAllText(path));if(Catalog==null||Catalog.Clips==null)throw new ArgumentException("语音目录格式无效");if(File.Exists(settingsPath)){Settings=json.Deserialize<VoiceSettings>(File.ReadAllText(settingsPath));if(Settings==null||Double.IsNaN(Settings.Volume)||Double.IsInfinity(Settings.Volume))throw new ArgumentException("语音设置格式无效");Settings.Volume=Math.Max(0,Math.Min(1,Settings.Volume));}}catch(Exception e){if(!(e is IOException)&&!(e is ArgumentException)&&!(e is UnauthorizedAccessException))throw;LoadError=e.Message;Status="原声配置读取失败，保留原文件："+e.Message;Settings=new VoiceSettings{Enabled=false};Catalog=new VoiceCatalog();}
  string candidates=Path.Combine(folder,"candidates","catalog.json");if(File.Exists(candidates))try{Candidates=json.Deserialize<VoiceCatalog>(File.ReadAllText(candidates))??new VoiceCatalog();if(Candidates.Clips==null)Candidates=new VoiceCatalog();foreach(var clip in Candidates.Clips){clip.Candidate=true;clip.Events=new string[0];}}catch(Exception e){if(!(e is IOException)&&!(e is ArgumentException)&&!(e is UnauthorizedAccessException))throw;Status="候选试听目录无法读取，原声库仍可使用";}
  player.MediaOpened+=(s,e)=>{OpenedCount++;if(!Playing)return;Status="正在播放："+(currentClip==null?CurrentId:currentClip.Chinese);player.Play();if(Started!=null&&currentClip!=null)Started(currentClip);Raise();};player.MediaEnded+=(s,e)=>{EndedCount++;if(Completed!=null)Completed();Stop();Status="播放完成";Raise();};player.MediaFailed+=(s,e)=>{Stop();Status="原声无法播放："+e.ErrorException.Message;Raise();};watchdog.Tick+=(s,e)=>{Stop();Status="原声播放超时，已停止";Raise();};if(Catalog.Clips.Count==0&&LoadError==null)Status="未找到语音素材，请检查voices目录";
 }
 public bool PlayEvent(string kind,string key,bool suppressed){if(kind==null)return false;if(kind=="click"&&!Settings.Interactions||kind=="reminder"&&!Settings.Reminders||kind!="click"&&kind!="reminder"&&!Settings.Workflows)return false;var candidates=Catalog.Clips.Where(c=>c.Events!=null&&Array.IndexOf(c.Events,kind)>=0).ToArray();if(candidates.Length==0)return false;int index=random.Next(candidates.Length);if(candidates.Length>1&&index==lastIndex)index=(index+1)%candidates.Length;var clip=candidates[index];bool accepted=Play(clip,kind,key,suppressed);if(accepted)lastIndex=index;return accepted;}
 public bool PlayAmbient(string action,bool suppressed,bool automatic=true){if(!Settings.Interactions||automatic&&!Settings.Ambient)return false;var candidates=Catalog.Clips.Where(c=>action=="travel"?c.Id=="skill2":c.Action==action&&(c.Id=="finish1"||c.Id=="finish2"||c.Id=="questclear"||c.Id=="lose")).ToArray();if(candidates.Length==0)return false;bool accepted=Play(candidates[random.Next(candidates.Length)],"ambient","ambient:"+action,suppressed);if(accepted){TravelVoice=action=="travel";AmbientVoice=automatic;}return accepted;}
 public bool PlayCountReminder(int count,bool suppressed){var clip=Catalog.Clips.FirstOrDefault(c=>c.Count==count&&c.Action=="count");return clip!=null&&Play(clip,"work-end",null,suppressed);}
 public bool PlayMonitorAlert(bool suppressed){if(Playing&&AmbientVoice)Stop();var clip=Catalog.Clips.FirstOrDefault(c=>c.Id=="damage1");return clip!=null&&Play(clip,"monitor-alert","monitor-alert",suppressed);}
 public bool Preview(VoiceClip clip){return Play(clip,"preview",null,false);}
 bool Play(VoiceClip clip,string kind,string key,bool suppressed){if(!Settings.Enabled||Settings.Volume<=0||clip==null){Status="原声已静音或关闭";Raise();return false;}if(!policy.CanPlay(kind,key,clock.Elapsed.TotalSeconds,clip.Seconds,Playing,suppressed))return false;if(String.IsNullOrEmpty(clip.File)||Path.GetFileName(clip.File)!=clip.File||!clip.File.EndsWith(".mp3",StringComparison.OrdinalIgnoreCase)||!File.Exists(Path.Combine(clip.Candidate?Path.Combine(folder,"candidates"):folder,clip.File))){Status="缺少本地语音："+clip.Id;Raise();return false;}Stop();Playing=true;CurrentId=clip.Id;CurrentKind=kind;CurrentKey=key;currentClip=clip;player.Volume=Settings.Volume;watchdog.Interval=TimeSpan.FromSeconds(Math.Max(10,clip.Seconds+5));watchdog.Start();policy.Mark(kind,key,clock.Elapsed.TotalSeconds,clip.Seconds);Status="正在载入："+clip.Chinese;try{player.Open(new Uri(Path.Combine(clip.Candidate?Path.Combine(folder,"candidates"):folder,clip.File)));Raise();return true;}catch(Exception e){if(!(e is IOException)&&!(e is ArgumentException)&&!(e is InvalidOperationException))throw;Stop();Status="原声无法打开："+e.Message;Raise();return false;}}
 public void SetVolume(double volume){Settings.Volume=Math.Max(0,Math.Min(1,volume));player.Volume=Settings.Volume;if(Settings.Volume<=0)Stop();}
 public void Apply(){player.Volume=Settings.Volume;if(!Settings.Enabled||Settings.Volume<=0||!Settings.Ambient&&AmbientVoice)Stop();if(LoadError!=null)throw new IOException("原设置读取失败，未覆盖："+LoadError);var temp=settingsPath+".tmp";File.WriteAllText(temp,json.Serialize(Settings),new UTF8Encoding(false));if(File.Exists(settingsPath))File.Replace(temp,settingsPath,null);else File.Move(temp,settingsPath);if(Settings.Enabled&&Settings.Volume>0&&!Playing)Status=Catalog.Clips.Count>0?"原声就绪":"未找到语音素材，请检查voices目录";Raise();}
 public void Stop(){watchdog.Stop();player.Close();Playing=false;TravelVoice=false;AmbientVoice=false;CurrentId=null;CurrentKind=CurrentKey=null;currentClip=null;Status=!Settings.Enabled?"原声已关闭":Settings.Volume<=0?"原声已静音":"播放已停止";Raise();}
 void Raise(){if(Changed!=null)Changed();}
 public void Dispose(){Stop();}
}
